"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["36587"],{98174(e){e.exports=JSON.parse('{"id":"FIN-686","slug":"annualized-return","term":"Annualized Return","also_known_as":[],"difficulty":"Intermediate","definition":"Annualized return is the average yearly rate of return an investment would need to earn, with compounding, to produce its total return over a period longer or shorter than a year.","explanation":["Investments are held for different lengths of time, so their total returns are hard to compare directly. Annualizing converts each return into an equivalent yearly rate.","For example, an investment that grows from 10,000 to 13,310 over three years has a total return of 33.1%. Its annualized return is 10%, because 10,000 growing at 10% a year for three years reaches 13,310. Simply dividing 33.1% by three would give 11%, which overstates the yearly rate because it ignores compounding.","Annualized return is the same idea as the compound annual growth rate. It is the standard way funds report performance over three, five or ten years.","Annualizing returns over periods shorter than a year can be misleading. A 5% gain in one month, annualized, would suggest a return of nearly 80% a year, which is unlikely to continue.","Annualized returns smooth out the path an investment took. Two investments with the same annualized return may have had very different ups and downs along the way, so volatility and drawdowns are also worth considering."],"note":"","total":1500,"prev":{"slug":"annual-report","term":"Annual Report"},"next":{"slug":"annuity","term":"Annuity"}}')}}]);